import { beforeEach, describe, expect, it, vi } from 'vitest';

// Story 23-S3 — the one guard. `requireSession()` admits only a valid session
// whose account has a username (a non-blank `displayName`, read from the
// session's user); anything else is sent to `/`, where a signed-out visitor
// signs in and an account without a username creates one.
// `requireAnySession()` admits any valid session, named or not: it exists only
// for saving a username. `hasUsername(session)` is the one definition of
// "has a username", which the front door uses to pick what it shows.
// Do not edit this file to match an implementation.

const mocks = vi.hoisted(() => ({ getSession: vi.fn(), headers: vi.fn() }));

vi.mock('@/lib/auth', () => ({ auth: { api: { getSession: mocks.getSession } } }));
vi.mock('next/headers', () => ({ headers: mocks.headers }));
vi.mock('next/navigation', () => ({
  redirect: (path: string) => { throw new Error(`redirect:${path}`); },
}));

import { hasUsername, requireAnySession, requireSession } from './require-session';

const requestHeaders = new Headers({ cookie: 'better-auth.session_token=token' });

function sessionFor(displayName: unknown, omit = false) {
  const user: Record<string, unknown> = { id: 'user-1', email: 'ada@example.test', name: '' };
  if (!omit) user.displayName = displayName;
  return { user, session: { id: 'session-1', userId: 'user-1' } };
}

const BLANK: Array<[string, unknown]> = [
  ['null', null],
  ['an empty string', ''],
  ['spaces', '   '],
  ['tabs and newlines', '\t\n '],
  ['a no-break space', '\u00a0'],
];

beforeEach(() => {
  vi.resetAllMocks();
  mocks.headers.mockResolvedValue(requestHeaders);
});

describe('23-S3-R1 requireSession: a session with a username', () => {
  it('sends a visitor without a session to /', async () => {
    mocks.getSession.mockResolvedValue(null);
    await expect(requireSession()).rejects.toThrow('redirect:/');
    expect(mocks.getSession).toHaveBeenCalledWith({ headers: requestHeaders });
  });

  it.each(BLANK)('sends an account whose username is %s to /', async (_label, displayName) => {
    mocks.getSession.mockResolvedValue(sessionFor(displayName));
    await expect(requireSession()).rejects.toThrow(/^redirect:\/$/);
  });

  it('sends an account whose session user carries no username field to /', async () => {
    mocks.getSession.mockResolvedValue(sessionFor(undefined, true));
    await expect(requireSession()).rejects.toThrow(/^redirect:\/$/);
  });

  it.each([['a number', 42], ['an object', { trim: () => 'x' }], ['an array', ['Ada']]])(
    'sends an account whose username is %s to /',
    async (_label, displayName) => {
      mocks.getSession.mockResolvedValue(sessionFor(displayName));
      await expect(requireSession()).rejects.toThrow(/^redirect:\/$/);
    },
  );

  it.each([['Ada'], ['  Lil Orange Fox  '], ['🦖']])('returns the session of an account named %j', async (name) => {
    const session = sessionFor(name);
    mocks.getSession.mockResolvedValue(session);
    await expect(requireSession()).resolves.toBe(session);
    expect(mocks.getSession).toHaveBeenCalledWith({ headers: requestHeaders });
  });
});

describe('23-S3-R2 requireAnySession: any valid session', () => {
  it('sends a visitor without a session to /', async () => {
    mocks.getSession.mockResolvedValue(null);
    await expect(requireAnySession()).rejects.toThrow(/^redirect:\/$/);
    expect(mocks.getSession).toHaveBeenCalledWith({ headers: requestHeaders });
  });

  it.each([...BLANK, ['Ada', 'Ada']])('returns the session of an account whose username is %s', async (_label, displayName) => {
    const session = sessionFor(displayName);
    mocks.getSession.mockResolvedValue(session);
    await expect(requireAnySession()).resolves.toBe(session);
  });
});

describe('23-S3-R3 hasUsername: the one definition', () => {
  it('is false without a session', () => {
    expect(hasUsername(null)).toBe(false);
  });

  it.each(BLANK)('is false when the username is %s', (_label, displayName) => {
    expect(hasUsername(sessionFor(displayName) as never)).toBe(false);
  });

  it('is false when the session user carries no username field, or a non-string one', () => {
    expect(hasUsername(sessionFor(undefined, true) as never)).toBe(false);
    expect(hasUsername(sessionFor(42) as never)).toBe(false);
    expect(hasUsername(sessionFor(['Ada']) as never)).toBe(false);
    expect(hasUsername(sessionFor({ trim: () => 'x' }) as never)).toBe(false);
  });

  it.each([['Ada'], ['  Lil Orange Fox  ']])('is true for %j', (name) => {
    expect(hasUsername(sessionFor(name) as never)).toBe(true);
  });
});
